 async function loadBlockMute(){const [b,m]=await Promise.all([api("/api/me/blocks"),api("/api/me/mutes")]);const bx=b.ok?await b.json():null;const mx=m.ok?await m.json():null;setBlockList((bx?.data??[]).map((x:{userId?:string;id?:string})=>x.userId??x.id??"").filter(Boolean));setMuteList((mx?.data??[]).map((x:{userId?:string;id?:string})=>x.userId??x.id??"").filter(Boolean))}
